function scheduleCloudSave(){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(()=>saveWorkspaceCloud().catch(err=>{console.warn('Cloud autosave failed',err);const b=$('.start-footer .cloud-state');if(b)b.textContent='☁ Sync issue'}),700)}
function localWorkspace(){const data={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('ngptos:'))data[k.slice(7)]=localStorage.getItem(k)}return data}
async function saveWorkspaceCloud(){if(!cloudClient||!cloudUser||!cloudReady)return;const {error}=await cloudClient.from('user_workspace').upsert({user_id:cloudUser.id,data:localWorkspace(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;const badge=$('.start-footer .cloud-state');if(badge)badge.textContent='☁ Saved'}
function setAuthMessage(message,success=false){const el=$('#auth-message');if(el){el.textContent=message;el.classList.toggle('success',success)}}
async function restoreWorkspaceCloud(){cloudReady=false;const local=localWorkspace();const {data,error}=await cloudClient.from('user_workspace').select('data').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;if(data?.data&&Object.keys(data.data).length){for(const [k,v] of Object.entries(data.data)){if(typeof v==='string')localStorage.setItem('ngptos:'+k,v)}}else if(Object.keys(local).length){cloudReady=true;await saveWorkspaceCloud()}cloudReady=true;const name=cloudUser.email||'NGPT OS user';const footer=$('.start-footer strong');if(footer)footer.textContent=name;const avatar=$('.user-avatar');if(avatar)avatar.textContent=name.slice(0,1).toUpperCase();let state=$('.start-footer .cloud-state');if(!state){state=document.createElement('small');state.className='cloud-state';$('.start-footer').insertBefore(state,$('#power-button'))}state.textContent='☁ Cloud sync on';applySettings();renderStart()}
async function authShowDesktop(user){cloudUser=user;$('#auth-screen').style.display='none';$('#desktop').style.display='';try{await restoreWorkspaceCloud();setAuthMessage('Signed in. Your workspace is syncing automatically.',true);$('#auth-message').textContent='';}catch(err){cloudReady=false;console.error('NGPT OS cloud restore:',err);toast('Cloud sync failed to load. Local data remains available.')}}
function setAuthMode(mode){authMode=mode;const login=mode==='login';$('#auth-tab-login').classList.toggle('active',login);$('#auth-tab-signup').classList.toggle('active',!login);$('#auth-heading').textContent=login?'Welcome to NGPT OS':'Create your NGPT OS account';$('#auth-submit').textContent=login?'Sign in securely':'Create account';$('#auth-reset').style.display=login?'block':'none';$('#auth-password').autocomplete=login?'current-password':'new-password';setAuthMessage('')}
async function initCloudAuth(){if(!window.supabase?.createClient){setAuthMessage('Could not load the secure sign-in service. Refresh this page to retry.');return}cloudClient=window.supabase.createClient(cloudProjectUrl,cloudPublishableKey);$('#auth-tab-login').onclick=()=>setAuthMode('login');$('#auth-tab-signup').onclick=()=>setAuthMode('signup');$('#auth-form').onsubmit=async e=>{e.preventDefault();if(authBusy)return;authBusy=true;const btn=$('#auth-submit');btn.disabled=true;setAuthMessage(authMode==='login'?'Signing in…':'Creating your account…');const email=$('#auth-email').value.trim(),password=$('#auth-password').value;try{const result=authMode==='login'?await cloudClient.auth.signInWithPassword({email,password}):await cloudClient.auth.signUp({email,password});if(result.error)throw result.error;if(authMode==='signup'&&!result.data.session){setAuthMessage('Account created. Check your email to confirm the address, then sign in.',true)}else if(result.data.user)await authShowDesktop(result.data.user)}catch(err){setAuthMessage(err.message||'Sign-in failed. Please try again.')}finally{authBusy=false;btn.disabled=false}};$('#auth-reset').onclick=async()=>{const email=$('#auth-email').value.trim();if(!email){setAuthMessage('Enter your email address first.');return}try{const {error}=await cloudClient.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;setAuthMessage('If that account exists, a password-reset email has been sent.',true)}catch(err){setAuthMessage(err.message||'Could not send reset email.')}};const {data,error}=await cloudClient.auth.getSession();if(error)console.warn(error);if(data?.session?.user)await authShowDesktop(data.session.user);else{$('#desktop').style.display='none';$('#auth-screen').style.display='flex'}cloudClient.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){cloudUser=null;cloudReady=false;$('#desktop').style.display='none';$('#auth-screen').style.display='flex'}else if(session?.user&&event==='SIGNED_IN'&&!cloudUser){authShowDesktop(session.user)}})}
async function uploadCloudFile(file){if(!cloudClient||!cloudUser)throw new Error('Sign in to upload files to cloud storage.');const id=crypto.randomUUID();const path=cloudUser.id+'/'+id+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const {error:uploadError}=await cloudClient.storage.from('ngptos-files').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(uploadError)throw uploadError;const {error:rowError}=await cloudClient.from('user_files').insert({user_id:cloudUser.id,name:file.name,storage_path:path,content_type:file.type||'application/octet-stream',size_bytes:file.size});if(rowError){await cloudClient.storage.from('ngptos-files').remove([path]);throw rowError}}
async function listCloudFiles(){if(!cloudClient||!cloudUser)return[];const {data,error}=await cloudClient.from('user_files').select('id,name,storage_path,content_type,size_bytes,created_at').eq('user_id',cloudUser.id).order('created_at',{ascending:false});if(error)throw error;return data||[]}
async function getCloudFileBlob(id){const {data:row,error}=await cloudClient.from('user_files').select('name,storage_path,content_type').eq('id',id).single();if(error)throw error;const {data,error:downloadError}=await cloudClient.storage.from('ngptos-files').download(row.storage_path);if(downloadError)throw downloadError;return {name:row.name,type:row.content_type,blob:data}}
async function downloadCloudFile(id){const f=await getCloudFileBlob(id);download(f.name,f.blob,f.type)}
async function previewCloudFile(id){const f=await getCloudFileBlob(id);const url=URL.createObjectURL(f.blob);const tab=window.open(url,'_blank');if(!tab){URL.revokeObjectURL(url);download(f.name,f.blob,f.type);toast('Pop-up blocked; downloaded the file instead.');return}setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function deleteCloudFile(id){const {data:row,error}=await cloudClient.from('user_files').select('storage_path').eq('id',id).single();if(error)throw error;const {error:storageError}=await cloudClient.storage.from('ngptos-files').remove([row.storage_path]);if(storageError)throw storageError;const {error:rowError}=await cloudClient.from('user_files').delete().eq('id',id);if(rowError)throw rowError}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;$('#toast-area').append(el);setTimeout(()=>el.remove(),3400)}
function fileNameSafe(s){return String(s||'file').replace(/[\\/:*?"<>|]/g,'_')}
function download(name,content,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type});const a=document.createElement('a');const u=URL.createObjectURL(blob);a.href=u;a.download=fileNameSafe(name);a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function appById(id){return apps.find(a=>a[0]===id)}
function setAccent(hex){document.documentElement.style.setProperty('--accent',hex);const n=hex.replace('#','');const rgb=[parseInt(n.slice(0,2),16),parseInt(n.slice(2,4),16),parseInt(n.slice(4,6),16)];document.documentElement.style.setProperty('--accent-rgb',rgb.join(','));write('accent',hex)}
function applySettings(){const s=read('settings',{theme:'dark',wallpaper:0,taskbar:'center',glass:true,scale:100,user:'Supervisor'});document.body.classList.toggle('light-mode',s.theme==='light');document.body.classList.toggle('no-glass',!s.glass);$('#taskbar').classList.toggle('taskbar-left-mode',s.taskbar==='left');$('#desktop-wallpaper').style.background=wallpapers[s.wallpaper]?.[1]||wallpapers[0][1];setAccent(read('accent','#4c91ff'));document.documentElement.style.fontSize=(s.scale||100)+'%';$('.start-footer strong').textContent=s.user||'Supervisor';$('.user-avatar').textContent=(s.user||'S').slice(0,1).toUpperCase()}
function getSettings(){return read('settings',{theme:'dark',wallpaper:0,taskbar:'center',glass:true,scale:100,user:'Supervisor'})}
function updateClock(){const d=new Date();$('#task-time').textContent=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#task-date').textContent=d.toLocaleDateString([],{month:'2-digit',day:'2-digit',year:'numeric'});$('#quick-date').textContent=d.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'});const clock=$('#clock-date');if(clock)clock.textContent=d.toLocaleDateString([],{weekday:'long',year:'numeric',month:'long',day:'numeric'});$$('[data-live-clock]').forEach(el=>el.textContent=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:!clock24}))}
function renderStart(q=''){const list=$('#app-list');list.innerHTML='';const filtered=apps.filter(a=>(a[1]+' '+a[3]).toLowerCase().includes(q.toLowerCase()));filtered.forEach(a=>{const b=document.createElement('button');b.className='app-pin';b.innerHTML='<span class="app-glyph">'+a[2]+'</span><span>'+esc(a[1])+'</span>';b.onclick=()=>{openApp(a[0]);$('#start-menu').classList.add('hidden')};list.append(b)});if(!filtered.length)list.innerHTML='<p class="muted">No apps found.</p>';const rec=$('#recommended-list');const recent=read('recent',[]).filter(id=>appById(id)).slice(0,4);rec.innerHTML=recent.length?'':'<span class="muted">Open an app and it will appear here.</span>';recent.forEach(id=>{const a=appById(id),b=document.createElement('button');b.innerHTML='<span style="font-size:23px">'+a[2]+'</span><span>'+esc(a[1])+'</span>';b.onclick=()=>{openApp(id);$('#start-menu').classList.add('hidden')};rec.append(b)})}
function openStart(){const m=$('#start-menu');m.classList.toggle('hidden');$('#quick-panel').classList.add('hidden');if(!m.classList.contains('hidden')){$('#app-search').value='';renderStart();$('#app-search').focus()}}
$('#start-button').onclick=openStart;$('#search-button').onclick=openStart;$('#app-search').oninput=e=>renderStart(e.target.value);$('#show-all-apps').onclick=()=>{$('#app-search').value='';renderStart();$('#app-search').focus()};$('#enter').onclick=()=>$('#welcome').classList.add('hidden');
$$('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open));
