$$('[data-quick]').forEach(b=>b.onclick=()=>{const v=b.dataset.quick;if(v==='theme'){const s=getSettings();s.theme=s.theme==='dark'?'light':'dark';write('settings',s);applySettings();toast('Theme changed')}else if(v==='settings')openApp('settings');else if(v==='lock'){openApp('locker');toast('Use File Locker to encrypt private files')}else toast('Network status is controlled by your device')});
