let voicePopup=null,voiceRecognition=null,voiceActive=false,voiceRequestId=0,voicePending=null,voiceMuted=false;
function ensureVoicePanel(){let p=$('#ngptos-voice-panel');if(p)return p;p=document.createElement('section');p.id='ngptos-voice-panel';p.className='ngptos-voice-panel';p.innerHTML='<div class="ngptos-voice-head"><span class="ngptos-voice-orb">🎙</span><div><strong>NGPT Live</strong><small id="ngptos-voice-status">Connecting to NGPT…</small></div><button id="ngptos-voice-close" title="Close assistant">×</button></div><div class="ngptos-voice-transcript" id="ngptos-voice-transcript">Tap the microphone to speak.</div><div class="ngptos-voice-actions"><button id="ngptos-voice-mic" class="primary">🎙 Start listening</button><button id="ngptos-voice-mute" class="soft-button">🔊 Voice on</button><button id="ngptos-voice-stop" class="soft-button">Stop</button></div><small class="ngptos-voice-note">Microphone permission is controlled by your browser. Your speech is sent to your signed-in NGPT account.</small>';document.body.append(p);$('#ngptos-voice-close').onclick=stopVoiceAssistant;$('#ngptos-voice-mute').onclick=()=>{voiceMuted=!voiceMuted;$('#ngptos-voice-mute').textContent=voiceMuted?'🔇 Voice off':'🔊 Voice on';if(voiceMuted)speechSynthesis.cancel()};$('#ngptos-voice-stop').onclick=()=>{voiceActive=false;try{voiceRecognition?.stop()}catch{}speechSynthesis.cancel();setVoiceStatus('Paused. Tap Start listening to continue.')};$('#ngptos-voice-mic').onclick=()=>startVoiceListening();return p}
function setVoiceStatus(s){const el=$('#ngptos-voice-status');if(el)el.textContent=s}
function stopVoiceAssistant(){voiceActive=false;try{voiceRecognition?.stop()}catch{}speechSynthesis.cancel();if(voicePopup&&!voicePopup.closed)voicePopup.close();voicePopup=null;$('#ngptos-voice-panel')?.remove()}
function startVoiceListening(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){setVoiceStatus('Speech recognition is not supported in this browser.');return}if(!voicePopup||voicePopup.closed){setVoiceStatus('Open NGPT Live first, then sign in if asked.');return}voiceActive=true;try{voiceRecognition?.abort()}catch{}voiceRecognition=new SR();voiceRecognition.lang=navigator.language||'en-GB';voiceRecognition.continuous=false;voiceRecognition.interimResults=true;voiceRecognition.onstart=()=>setVoiceStatus('Listening…');voiceRecognition.onerror=e=>{setVoiceStatus(e.error==='not-allowed'?'Allow microphone access in your browser.':'Microphone: '+e.error);if(e.error==='not-allowed')voiceActive=false};voiceRecognition.onresult=e=>{let interim='',finalText='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=t;else interim+=t}const display=$('#ngptos-voice-transcript');if(display&&interim)display.textContent=interim;if(finalText.trim()){const msg=finalText.trim();if(display)display.textContent='You: '+msg;voicePending={id:String(++voiceRequestId),message:msg};if(voicePopup&&!voicePopup.closed){voicePopup.postMessage({type:'NGPTOS_VOICE_REQUEST',...voicePending},'https://ngptai010.vercel.app');setVoiceStatus('Thinking…')}else setVoiceStatus('NGPT Live tab closed. Reopen the assistant.')}};voiceRecognition.onend=()=>{if(voiceActive&&$('#ngptos-voice-panel'))setVoiceStatus('Ready for your next turn…')};try{voiceRecognition.start()}catch(e){setVoiceStatus('Could not start microphone. Tap Start listening again.')}} 
window.addEventListener('message',e=>{if(e.origin!=='https://ngptai010.vercel.app'||e.source!==voicePopup)return;const d=e.data||{};if(d.type==='NGPTOS_VOICE_READY'){setVoiceStatus('Connected to NGPT. Say something.')}else if(d.type==='NGPTOS_VOICE_REPLY'&&voicePending&&d.id===voicePending.id){const reply=String(d.reply||'');const display=$('#ngptos-voice-transcript');if(display)display.textContent='NGPT: '+reply;setVoiceStatus('NGPT replied');if(reply&&!voiceMuted&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(reply);u.onend=()=>{if(voiceActive&&$('#ngptos-voice-panel'))setTimeout(()=>startVoiceListening(),350)};speechSynthesis.speak(u)}else if(voiceActive)setTimeout(()=>startVoiceListening(),350);voicePending=null}else if(d.type==='NGPTOS_VOICE_ERROR'){setVoiceStatus(d.error||'NGPT could not reply. Check you are signed in.');voicePending=null}});
function launchVoiceAssistant(){ensureVoicePanel();const url='https://ngptai010.vercel.app/?openLive=1&ngptosVoiceBridge=1';if(!voicePopup||voicePopup.closed)voicePopup=window.open(url,'ngptos-live-assistant');if(!voicePopup){setVoiceStatus('Pop-up blocked. Allow pop-ups for NGPT OS and try again.');return}setVoiceStatus('Connecting to NGPT…');const ping=()=>{try{if(voicePopup&&!voicePopup.closed)voicePopup.postMessage({type:'NGPTOS_VOICE_HELLO'},'https://ngptai010.vercel.app')}catch{}};ping();setTimeout(ping,700);setTimeout(ping,1600);startVoiceListening()}

