if(id==='exe')return '<h1 class="app-heading">EXE Folder</h1><p class="muted-copy">A place to keep Windows installer files you upload. Browsers cannot run .exe files.</p><div class="file-toolbar"><button class="primary" data-action="exe-add">＋ Add EXE files</button><input id="exe-upload" type="file" accept=".exe,.msi,.bat,.cmd,.zip" multiple hidden></div><div id="exe-list" class="file-list"></div><p class="notice">For safety, this is storage only: it does not execute files. In a future native Windows app, opening executables would need explicit permissions and security checks.</p>';if(id==='locker')return '<h1 class="app-heading">File Locker</h1><p class="muted-copy">A password-encrypted vault stored in this browser on this device.</p><div id="locker-content"><div class="locker-box"><div style="font-size:35px">🔐</div><h3>Unlock or create your vault</h3><p class="muted-copy">Choose a strong, unique password. If you forget it, this preview cannot recover your files.</p><label>Vault password<input id="vault-password" type="password" autocomplete="current-password" class="field" placeholder="Enter a vault password"></label><button class="primary" id="vault-unlock">Unlock / Create vault</button><p class="muted-copy" id="vault-message"></p></div></div>';
