if(id==='settings')return '<h1 class="app-heading">Settings</h1><p class="muted-copy">Make NGPT OS feel like yours.</p><div class="setting-tabs"><button class="selected" data-settings-tab="personal">Personalisation</button><button data-settings-tab="system">System</button><button data-settings-tab="account">Account</button><button data-settings-tab="about">About</button></div><div id="settings-content"></div>';
