if(id==='calendar')return '<div class="calendar-head"><button class="soft-button" data-action="prev-month">←</button><h1 class="app-heading" id="month-title"></h1><button class="soft-button" data-action="next-month">→</button></div><div id="calendar-grid" class="calendar-grid"></div>';
if(id==='clock')return '<div class="clock-face" data-live-clock>--:--:--</div><div class="clock-date" id="clock-date"></div><div style="text-align:center;margin-top:28px"><button class="soft-button" data-action="clock-format">Toggle 12/24-hour time</button></div>';
if(id==='paint')return '<h1 class="app-heading">Paint</h1><div class="paint-tools"><label>Colour <input id="paint-color" type="color" value="#222222"></label><label>Brush <input id="paint-size" type="range" min="1" max="30" value="5"></label><button class="soft-button" data-action="paint-clear">Clear</button><button class="primary" data-action="paint-save">Save PNG</button></div><canvas id="paint-canvas" width="1200" height="600"></canvas>';
